        # Not using multi-column index on a single column.
        if len(columns) == 1:
            return self.sql_delete_index % {
                'table': self.quote_name(model._meta.db_table),
                'name': self.quote_name(index_name),
            }
        # The index name is unique for the table, so we can use it to
        # find the index.
        constraints = self.connection.introspection.get_constraints(
            model._meta.db_table, self.connection.introspection.connection
        )
        # The index might be a unique constraint, so we need to check
        # for that as well.
        for name, details in constraints.items():
            if details['columns'] == columns and details['primary_key'] is False:
                if details['unique']:
